 const gs=x.gotsport,competition=gs&&competitionResourceMatch(gs,state.gotsport?.competitions||state.gotsport?.tournaments||[]),kind=competition?.kind;
 if(gs){const type=['league','tournament'].includes(kind)?kind:'competition';return {type,label:{league:'League',tournament:'Tournaments',competition:'Other competitions'}[type],competition:'event:'+(gs.event_id||gs.competition||'unknown'),name:competition?.name||gs.competition||'Competition'};}
