 const req=sourceRequests[name]||{},d=state.data||{},t=state.trace||{},g=state.gotsport||{},s=name==='Trace'?(t.status||{}):name==='GotSport'?g:d,p=name==='Trace'?(s.progress||{}):name==='GotSport'?(s.progress||{}):(d.sync_progress||{}),tasks=Array.isArray(p.tasks)?p.tasks:[];
 const stamp=v=>typeof v==='number'?v:Date.parse(v||'');
 const fresh=v=>Number.isFinite(stamp(v))&&Date.now()-stamp(v)<120000;
 const loaded=name==='Trace'?!!(t.dataLoaded||t.status):name==='GotSport'?g.loaded===true||(g.loaded!==false&&!!g.sync_status):!!state.data;
 const count=name==='Trace'?(t.rows||[]).length:name==='GotSport'?(g.events||[]).length:(d.events||[]).length;
 const error=sourceStatusText(req.error||sourceErrors.get(name)||s.sync_error||p.error||tasks.find(t=>t.error)?.error);
 const last=s.last_sync_at||s.data_updated_at||s.updated_at;
 const out=(kind,label)=>({kind,label,count,last,lastSuccess:s.last_sync_at||s.data_updated_at||null,resultsLastSuccess:name==='GotSport'?s.results_last_success_at||null:null,coverage:name==='GotSport'?s.coverage||null:null,name,loaded,error:error||'',reconnect:name==='Trace'&&traceNeedsAuth(s),retryAt:p.retry_at||p.tasks?.retry_at||tasks.find(t=>t.retry_at)?.retry_at||null});
