function mergeCorrections(prior=[],next=[]){const merged=new Map();for(const c of [...prior,...next]){const key=JSON.stringify([c.season,c.player_key,c.game_id||'']),old=merged.get(key);if(!old||String(c.updated_at||'')>=String(old.updated_at||''))merged.set(key,c)}return [...merged.values()]}
