 if(!snapshotCache.scope)return;const scope=snapshotCache.scope,epoch=snapshotCache.epoch;if(revision){const prior=snapshotCache.signatures.get(key);if(Array.isArray(prior)&&prior.length===revision.length&&prior.every((v,i)=>Object.is(v,revision[i])))return;}const signature=revision||JSON.stringify(value);if(snapshotCache.signatures.get(key)===signature)return;snapshotCache.signatures.set(key,signature);
