function dashboardContent(z){const t=z.team||{},g=z.gotsport||{};return JSON.stringify([t.team,t.events,t.members,t.locations,t.opponents,t.availabilities,t.kit_overrides,t.player_corrections,g.team_id,g.team_name,g.events,g.competitions,g.tournaments,z.mapping?.player_map,z.mapping?.game_map,(z.profiles||[]).map(p=>[p.team_id,p.name,p.logo,p.club_name]),z.logo_overrides,z.club_kits,z.favorites])+'\\n'+traceContentSignature(z.trace);}
