 for(const [key,label] of Object.entries({gotsport:'GotSport',trace:'Trace',mapping:'Trace mapping',favorites:'Favorites'})){sourceRequest(label,false,z.errors?.[key]||'');sourceError(label,z.errors?.[key]||'');}
