const KIT_COLORS={Black:'#111111',White:'#ffffff',Red:'#dc2626',Gray:'#808080',Blue:'#2563eb',Navy:'#172554',Green:'#15803d',Yellow:'#facc15',Orange:'#f97316',Purple:'#9333ea',Pink:'#ec4899'};
function kitNameKey(name){return String(name||'').trim().replace(/\\s+/g,' ').toLowerCase()}
function kitColor(kit){if(/^#[0-9a-f]{6}$/i.test(kit?.color||''))return kit.color;const name=kitNameKey(kit?.name).replace(/\\s+(kit|uniform|jersey)$/,'').replace(/^grey$/,'gray');return Object.entries(KIT_COLORS).find(([key])=>key.toLowerCase()===name)?.[1]||'';}
