 identityElements(root,'[data-team-display]').forEach(n=>{const p=teamDisplayRecord(n.dataset.teamDisplay,n.dataset.teamSourceName,n.dataset.teamSourceLogo,!!n.dataset.teamFull),signature=JSON.stringify([p,isOwnTeam(n.dataset.teamDisplay),n.dataset.teamFavoriteControl,n.dataset.teamCopy]);if(n.dataset.teamSignature===signature)return;n.dataset.teamSignature=signature;n.innerHTML=teamBadgeHtml(n.dataset.teamDisplay,p.logo,n.dataset.teamSize)+teamDisplayLabelHtml(n.dataset.teamDisplay,p.name,n.dataset.teamQuery,!!n.dataset.teamFavoriteControl,n.dataset.teamCopy?p.fullName:'');const link=n.closest('[data-team-history]');if(link)link.dataset.teamName=p.name;});
