const pendingTeamIdentityRoots=new Set();
async function hydrateTeamIdentities(root=document){
 pendingTeamIdentityRoots.add(root);if(dashboardLoading||teamProfilesLoading)return;
 teamProfilesLoading=true;
 try{while(pendingTeamIdentityRoots.size&&!dashboardLoading){
  const candidates=[...pendingTeamIdentityRoots].filter(r=>r===document||r.isConnected);pendingTeamIdentityRoots.clear();
  const roots=candidates.filter(r=>!candidates.some(parent=>parent!==r&&parent.contains(r)));
  for(const node of roots)paintTeamIdentities(node);
  const ids=[...new Set(roots.flatMap(node=>identityElements(node,'[data-team-display]')).filter(n=>n.getClientRects().length).map(n=>n.dataset.teamDisplay))].filter(id=>Date.now()>=(teamProfiles.get(id)?.next_at||0));
  if(!ids.length)continue;const batch=ids.slice(0,8);if(ids.length>8)for(const node of roots)pendingTeamIdentityRoots.add(node);
  try{const result=await api('/api/team-profiles?'+new URLSearchParams({ids:batch.join(',')}));for(const id of batch){const p=result.profiles?.find(p=>String(p.team_id)===id);teamProfiles.set(id,{...teamProfiles.get(id),...p,next_at:Number(p?.next_at)>Date.now()?Number(p.next_at):Date.now()+300000});recordTeamIdentity('profile:'+id,{stage:'profile',team_id:id,state:p?.state||(p?.logo?'ready':p?.name?'missing_logo':'unavailable'),error:p?.error||null,next_at:p?.next_at||null});}}
  catch(e){for(const id of batch){teamProfiles.set(id,{...teamProfiles.get(id),next_at:Date.now()+300000});recordTeamIdentity('profile:'+id,{stage:'profile',team_id:id,state:'request_failed',error:e.message,http_status:e.status||null});}}
  for(const node of roots)if(node===document||node.isConnected)paintTeamIdentities(node);persistDashboard();
 }}finally{teamProfilesLoading=false;}
}
function startTeamIdentityObserver(){
 const relevant=node=>node.nodeType===1&&(node.matches?.('[data-team-display],[data-team-kits]')||node.querySelector?.('[data-team-display],[data-team-kits]'));
 const observer=new MutationObserver(records=>{const roots=new Set();for(const record of records){if(record.type==='attributes'){if(relevant(record.target))roots.add(record.target);}else for(const node of record.addedNodes)if(relevant(node))roots.add(node);}for(const root of roots)void hydrateTeamIdentities(root);});
 observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class','open','hidden']});document.addEventListener('visibilitychange',()=>{if(!document.hidden)void hydrateTeamIdentities()});
}
