function matchHasPlayerStats(item){return !!item.game&&!itemCancelled(item)&&rowsForGame(item.game.game_id).length>0}

// Cached stats retain their verified owning source; viewing another team grants no access.
function sameStatsFixture(a,b){return !!(a?.event_id&&a?.match_id&&b?.event_id&&b?.match_id&&String(a.event_id)===String(b.event_id)&&String(a.match_id)===String(b.match_id)&&sameGotSportFixture(a,b));}
