 for(const item of allMatchItems()){
  const gs=item.gotsport,g=item.game;
  if(!g?.game_id||!gs?.event_id||!gs?.match_id||!item.fixture_identity_verified||item.reconciliation_ambiguous||itemCancelled(item)||gs.watch_unavailable||fixtureHasPendingParticipants(gs))continue;
  if(!['home','away'].includes(gs.team_side)||String(gs[gs.team_side+'_team_id']||'')!==own)continue;
  const count=rowsForGame(g.game_id).length;if(!count)continue;
  fixtures.push({gameId:String(g.game_id),eventId:item.event?.id==null?'':String(item.event.id),rowCount:count,rowEvidence:matchStatsRowsEvidence(state.trace,g.game_id),gotsport:{uid:gs.uid,match_id:gs.match_id,event_id:gs.event_id,home_team_id:gs.home_team_id,away_team_id:gs.away_team_id,start_at:gs.start_at,match_date:gs.match_date,...(gs.source_provider==='gotsport_live'?{source_provider:gs.source_provider,live_organizer_id:gs.live_organizer_id,live_game_id:gs.live_game_id,live_home_team_id:gs.live_home_team_id,live_away_team_id:gs.live_away_team_id,public_participants_resolved:gs.public_participants_resolved,conditional:gs.conditional}:{})}});
 }
