 const primary=viewingFollowedTeam()?connectedContext?{team:connectedContext.data,trace:connectedContext.trace,gotsport:connectedContext.gotsport,statsSource:connectedContext.statsSource}:null:{team:state.data,trace:state.trace,gotsport:state.gotsport,statsSource:null};
