   if(item.game&&String(item.game.game_id)!==fixture.gameId||item.event&&String(item.event.id)!==fixture.eventId)continue;
   if(!(trace.games||[]).some(g=>String(g.game_id)===fixture.gameId)||fixture.rowEvidence!==matchStatsRowsEvidence(trace,fixture.gameId))continue;
   const listed=(snapshot.gotsport.events||[]).filter(gs=>sameStatsFixture(gs,fixture.gotsport));
   if(listed.length!==1||itemCancelled({gotsport:listed[0]})||listed[0].watch_unavailable)continue;
   if(fixture.eventId&&(snapshot.team.events||[]).some(e=>String(e.id)===fixture.eventId&&eventIsCancelled(e)))continue;
