// User-triggered replacements share a non-blocking, compositor-only transition.
// Never animate the fixed selection background or overwrite Embla's transforms.
const dateViewAnimations=new WeakMap();
function animateDateView(node){
 if(!node)return;
 dateViewAnimations.get(node)?.cancel();dateViewAnimations.delete(node);
 if(matchMedia('(prefers-reduced-motion: reduce)').matches||!node.animate)return;
 const animation=node.animate([{opacity:.45},{opacity:1}],{duration:160,easing:'ease-out'});
 dateViewAnimations.set(node,animation);
 const cleanup=()=>{if(dateViewAnimations.get(node)===animation)dateViewAnimations.delete(node)};
 animation.onfinish=cleanup;animation.oncancel=cleanup;
}
function animateScheduleView(){for(const node of $$('.schedule-date-track,.schedule-day-surface'))animateDateView(node)}
function updateMatchResults(){$$('[data-period]').forEach(b=>{b.classList.toggle('active',b.dataset.period===state.matchPeriod);b.setAttribute('aria-pressed',String(b.dataset.period===state.matchPeriod))});const list=$('#matchList');if(!list)return;list.innerHTML=scheduleRowsHtml(filteredMatchItems());bindCommon();animateDateView(list)}
