 $$('[data-watch-game]').forEach(b=>{b.dataset.watchGame=favoriteControlKey(b);const saved=store.games.has(b.dataset.watchGame);b.setAttribute('aria-pressed',String(saved));b.disabled=favoriteControlPending(b,store);b.setAttribute('aria-label',bookmarkControlLabel(saved));b.title=bookmarkControlLabel(saved);b.innerHTML=bookmarkControlHtml(saved)});
