function applyFavoriteResponse(store,z){store.teams=new Map((z.teams||[]).map(t=>[t.team_id,t]));store.games=new Map((z.games||[]).map(g=>[g.key,g]));store.loaded=true;store.shared=z.shared;store.error=[...new Set((z.games||[]).map(x=>x.error).filter(Boolean))].join(' ');}
