 store.busy=true;const version=store.revision;
 try{const z=await api('/api/favorites/refresh?'+new URLSearchParams({key:familyKey(),day:localEventDay(new Date()),...(force?{force:'1'}:{})}),{method:'POST'});if(version===store.revision){const priorError=store.error;applyFavoriteResponse(store,z);if(store.error&&store.error!==priorError&&scope===favoriteScopeKey())toast('Bookmarks update delayed',store.error,'error')}}catch(e){store.error=e.message;if(scope===favoriteScopeKey())toast('Bookmarks update delayed',e.message+' Previously loaded games remain available.','error')}
